const paid = new Set<string>();
export const book = (slot: string) => ({ slot, status: 'booked' });
export const cancel = (b: { at: number }, now = Date.now()) => ({ status: 'cancelled', refund: now - b.at < 24 * 3600e3 });
export const pay = (key: string) => (paid.has(key) ? 'duplicate' : (paid.add(key), 'charged'));

const paid = new Set<string>();
export const book = (slot: string, people = 1) => ({ slot, people, status: 'booked' });
export const cancel = (b: { at: number }, now = Date.now()) => ({ status: 'cancelled', refund: now - b.at < 24 * 3600e3 });
export const pay = (key: string) => (paid.has(key) ? 'duplicate' : (paid.add(key), 'charged'));
